/**
 * MEMBERSHIP INTEGRITY — Server-Side Handler
 *
 * Mirrors BookingHandler. Enforces the membership business contract:
 *  - member_number is generated by the DB sequence default — NEVER accepted
 *    from the client (WRITABLE_FIELDS excludes it).
 *  - annual_price_snapshot / registration_fee_snapshot are captured
 *    server-side from the plan at assign/renew time (booking price-snapshot
 *    principle) — NEVER accepted from the client.
 *  - registered_at / expires_at are server-derived (annual period) — the
 *    client cannot control the period.
 *  - Lifecycle transitions are validated via STATUS_TRANSITIONS
 *    (pending→active/cancelled; active→cancelled/expired;
 *    expired→cancelled; cancelled terminal — no automatic renewal;
 *    cancel is explicit).
 *  - Assignment requires the plan to exist. Admins can assign ANY plan
 *    (including inactive plans, e.g. Bronze); public visibility is
 *    controlled separately via frontend filtering, NOT server rejection.
 *    Duplicate active memberships on the same plan for the same customer
 *    are blocked.
 */

import { Repository } from "./repository";
import {
  validationErr,
  conflictErr,
  notFoundErr,
  internalErr,
  type ActionResult,
} from "./validation/admin";
import type { SupabaseClient } from "@supabase/supabase-js";

const MEMBERSHIP_STATUSES = ["pending", "active", "expired", "cancelled"] as const;
type MembershipStatus = (typeof MEMBERSHIP_STATUSES)[number];

/** Admin-driven lifecycle transitions. `cancelled` is terminal. */
const STATUS_TRANSITIONS: Record<MembershipStatus, MembershipStatus[]> = {
  pending: ["active", "cancelled"],
  active: ["cancelled", "expired"],
  expired: ["cancelled"],
  cancelled: [],
};

/** Server-derived columns the handler is allowed to write (repo extraAllowed). */
const ASSIGN_SERVER_FIELDS = [
  "registered_at",
  "expires_at",
  "annual_price_snapshot",
  "registration_fee_snapshot",
];
const RENEW_SERVER_FIELDS = ["expires_at", "annual_price_snapshot", "registration_fee_snapshot"];

export function isMembershipResource(resource: string): boolean {
  return resource === "customer-memberships";
}

function addYears(from: Date, years: number): Date {
  const d = new Date(from.getTime());
  d.setFullYear(d.getFullYear() + years);
  return d;
}

export class MembershipHandler {
  constructor(private repo: Repository) {}

  private get supabase(): SupabaseClient<any> {
    return (this.repo as any).supabase as SupabaseClient<any>;
  }
    /**
   * Assign a membership (POST /api/admin/customer-memberships).
   *
   * Supports two workflows:
   *   1. Direct creation — client supplies full_name, phone, plan_id (customer is
   *      auto-resolved or created canonically; no second identity system).
   *   2. Customer-link creation — client supplies customer_id, plan_id (existing
   *      canonical customer). Retained for backward compatibility.
   *
   * The server generates: member_number (DB sequence), price snapshots, and the
   * annual expiry period. The client NEVER controls these authoritative fields.
   */
  async create(data: unknown): Promise<ActionResult<any>> {
    const body = (data ?? {}) as Record<string, any>;
    const planId = typeof body.plan_id === "string" ? body.plan_id : "";
    const notes = typeof body.notes === "string" && body.notes.trim() !== "" ? body.notes : null;

    if (!planId) return validationErr("plan_id is required");

    // Plan must exist. Admins can assign ANY plan (including Bronze/inactive plans).
    // Public visibility is controlled separately via frontend filtering, NOT server rejection.
    const { data: plan, error: planError } = await this.supabase
      .from("membership_plans")
      .select("id, name, slug, annual_price, registration_fee, is_active")
      .eq("id", planId)
      .maybeSingle();
    if (planError) return internalErr(planError.message);
    if (!plan) return validationErr("Membership plan not found");

    // Resolve the canonical customer identity. If the client provided a
    // customer_id, link to it. Otherwise auto-resolve by phone, or create a
    // new customer record — never a second identity system.
    let customerId: string;

    if (typeof body.customer_id === "string" && body.customer_id) {
      // Verify the supplied customer exists in the canonical table.
      const { data: customer, error: customerError } = await this.supabase
        .from("customers")
        .select("id")
        .eq("id", body.customer_id)
        .maybeSingle();
      if (customerError) return internalErr(customerError.message);
      if (!customer) return validationErr("Customer not found");
      customerId = body.customer_id;
    } else {
      // Direct member creation: resolve or create by phone number.
      const fullName = typeof body.full_name === "string" ? body.full_name.trim() : "";
      const phone = typeof body.phone === "string" ? body.phone.trim() : "";

      if (!fullName) return validationErr("full_name is required for direct member creation");
      if (!phone) return validationErr("phone is required for direct member creation");

      // Normalize phone using the canonical database function (handles Kenyan 07XX → +2547XX).
      // This prevents duplicate customers from equivalent phone formats (0712345678 vs +254712345678).
      const { data: normalizedResult, error: normalizeErr } = await this.supabase
        .rpc("normalize_customer_phone", { p_phone: phone });
      if (normalizeErr) return internalErr(`Phone normalization failed: ${normalizeErr.message}`);
      
      const phoneNormalized = normalizedResult as string | null;
      if (!phoneNormalized) return validationErr("Invalid phone number format");

      // Canonical customer resolution by normalized phone (UNIQUE constraint prevents duplicates).
      const { data: existingCustomer, error: findErr } = await this.supabase
        .from("customers")
        .select("id")
        .eq("phone_normalized", phoneNormalized)
        .maybeSingle();
      if (findErr) return internalErr(findErr.message);

      if (existingCustomer) {
        customerId = existingCustomer.id;
      } else {
        // Auto-create canonical customer (source = "manual" by admin).
        // Store both raw phone (for display) and normalized phone (for deduplication).
        const { data: newCustomer, error: createCustError } = await this.supabase
          .from("customers")
          .insert({
            full_name: fullName,
            phone: phone,
            phone_normalized: phoneNormalized,
            source: "manual",
          })
          .select("id")
          .single();
        if (createCustError) return this.handleDatabaseError(createCustError, "create customer");
        if (!newCustomer) return internalErr("Failed to create customer");
        customerId = newCustomer.id;
      }
    }

    // One active membership per customer per plan.
    const { data: duplicate, error: dupError } = await this.supabase
      .from("customer_memberships")
      .select("id, member_number")
      .eq("customer_id", customerId)
      .eq("plan_id", planId)
      .eq("status", "active")
      .maybeSingle();
    if (dupError) return internalErr(dupError.message);
    if (duplicate) {
      return conflictErr(
        `Customer already holds an active ${plan.name} membership (${duplicate.member_number})`
      );
    }

    const registeredAt = new Date();
    const expiresAt = addYears(registeredAt, 1);

    try {
      // member_number: omitted → DB sequence default generates ZT-M-00001.
      // Snapshots: taken from the plan row the server just loaded.
      const created = await this.repo.create(
        "customer-memberships",
        {
          customer_id: customerId,
          plan_id: planId,
          status: "active",
          notes,
          registered_at: registeredAt.toISOString(),
          expires_at: expiresAt.toISOString(),
          annual_price_snapshot: plan.annual_price,
          registration_fee_snapshot: plan.registration_fee,
        },
        ASSIGN_SERVER_FIELDS
      );
      return { success: true, data: created };
    } catch (error: any) {
      return this.handleDatabaseError(error, "create");
    }
  }
  /**
   * Admin edit (PATCH /api/admin/customer-memberships/:id).
   * Only `status` (with transition validation) and `notes` are admin-editable.
   */
  async update(id: string, body: unknown): Promise<ActionResult<any>> {
    const data = (body ?? {}) as Record<string, any>;
    const patch: Record<string, any> = {};

    if (data.notes !== undefined) {
      if (data.notes !== null && typeof data.notes !== "string") {
        return validationErr("notes must be a string");
      }
      patch.notes = data.notes;
    }

    if (data.status !== undefined) {
      if (typeof data.status !== "string" || !MEMBERSHIP_STATUSES.includes(data.status as any)) {
        return validationErr("Invalid membership status");
      }
      const current = await this.repo.findById("customer-memberships", id);
      if (!current) return notFoundErr("Membership not found");
      const nextStatus = data.status as MembershipStatus;
      if (current.status !== nextStatus) {
        const allowed = STATUS_TRANSITIONS[current.status as MembershipStatus] ?? [];
        if (!allowed.includes(nextStatus)) {
          return conflictErr(`Invalid membership transition: ${current.status} → ${nextStatus}`);
        }
      }
      patch.status = nextStatus;
    }

    if (Object.keys(patch).length === 0) {
      const current = await this.repo.findById("customer-memberships", id);
      if (!current) return notFoundErr("Membership not found");
      return { success: true, data: current };
    }

    try {
      const updated = await this.repo.update("customer-memberships", id, patch);
      return { success: true, data: updated };
    } catch (error: any) {
      return this.handleDatabaseError(error, "update");
    }
  }

  /**
   * Explicit renewal (POST /api/admin/customer-memberships/:id/renew).
   * Extends the annual period from max(current expiry, now) and re-snapshots
   * prices from the plan's CURRENT pricing (new period = new pricing).
   * Historical pricing is preserved in activity_logs via the route audit call.
   */
  async renew(id: string): Promise<ActionResult<any>> {
    const current = await this.repo.findById("customer-memberships", id);
    if (!current) return notFoundErr("Membership not found");
    const status = current.status as MembershipStatus;
    if (status !== "active" && status !== "expired") {
      return conflictErr(`Cannot renew a ${status} membership`);
    }

    const { data: plan, error: planError } = await this.supabase
      .from("membership_plans")
      .select("id, annual_price, registration_fee")
      .eq("id", current.plan_id)
      .maybeSingle();
    if (planError) return internalErr(planError.message);
    if (!plan) return notFoundErr("Membership plan not found");

    const currentExpiry = current.expires_at ? new Date(current.expires_at) : new Date();
    const base = currentExpiry.getTime() > Date.now() ? currentExpiry : new Date();
    const expiresAt = addYears(base, 1);

    try {
      const updated = await this.repo.update(
        "customer-memberships",
        id,
        {
          status: "active",
          expires_at: expiresAt.toISOString(),
          annual_price_snapshot: plan.annual_price,
          registration_fee_snapshot: plan.registration_fee,
        },
        RENEW_SERVER_FIELDS
      );
      return { success: true, data: updated };
    } catch (error: any) {
      return this.handleDatabaseError(error, "renew");
    }
  }

  /**
   * Explicit cancellation (POST /api/admin/customer-memberships/:id/cancel).
   * Preserves the record — cancellation is lifecycle state, never deletion.
   */
  async cancel(id: string): Promise<ActionResult<any>> {
    const current = await this.repo.findById("customer-memberships", id);
    if (!current) return notFoundErr("Membership not found");
    if (current.status === "cancelled") {
      return { success: true, data: current };
    }
    try {
      const updated = await this.repo.update(
        "customer-memberships",
        id,
        {
          status: "cancelled",
        },
        // Membership lifecycle authority: status is server-controlled for
        // lifecycle transitions (generic client writes excluded by design).
        // Pass as serverFields so the write path admits this handler-owned
        // transition instead of sanitizing to an empty no-op payload.
        ["status"]
      );
      return { success: true, data: updated };
    } catch (error: any) {
      return this.handleDatabaseError(error, "cancel");
    }
  }

  private handleDatabaseError(error: any, op: string): ActionResult<any> {
    const message = String(error?.message ?? "Unknown database error");
    if (/duplicate key/i.test(message)) {
      return conflictErr(`Membership ${op} failed: duplicate member number`);
    }
    if (/foreign key/i.test(message) || /violates/i.test(message)) {
      return validationErr(`Membership ${op} failed: ${message}`);
    }
    return internalErr(message);
  }
}
